package com.personal.assistant.module.knowledge.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.knowledge.dto.*;import com.personal.assistant.module.knowledge.entity.KnowledgeEntry;import com.personal.assistant.module.knowledge.service.KnowledgeService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/knowledge")public class KnowledgeController{private final KnowledgeService service;public KnowledgeController(KnowledgeService service){this.service=service;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping public ApiResponse<List<KnowledgeEntry>>list(@RequestParam(required=false)String keyword,@RequestParam(required=false)String topic,@RequestParam(defaultValue="false")boolean dueOnly){return ApiResponse.success(service.list(uid(),keyword,topic,dueOnly));}@PostMapping public ApiResponse<Long>create(@Valid @RequestBody KnowledgeRequest r){return ApiResponse.success(service.create(uid(),r));}@PutMapping("/{id}")public ApiResponse<Void>update(@PathVariable Long id,@Valid @RequestBody KnowledgeRequest r){service.update(uid(),id,r);return ApiResponse.success();}@PostMapping("/import")public ApiResponse<Long>importSource(@Valid @RequestBody KnowledgeImportRequest r){return ApiResponse.success(service.importSource(uid(),r));}@PostMapping("/{id}/links")public ApiResponse<Void>link(@PathVariable Long id,@Valid @RequestBody KnowledgeLinkRequest r){service.link(uid(),id,r);return ApiResponse.success();}@GetMapping("/{id}/links")public ApiResponse<List<KnowledgeEntry>>links(@PathVariable Long id){return ApiResponse.success(service.backlinks(uid(),id));}@GetMapping("/{id}/similar")public ApiResponse<List<KnowledgeEntry>>similar(@PathVariable Long id){return ApiResponse.success(service.similar(uid(),id));}@PostMapping("/{id}/review")public ApiResponse<Void>review(@PathVariable Long id,@RequestParam boolean remembered){service.review(uid(),id,remembered);return ApiResponse.success();}}
